{"text":"export const maxDrawdown = (values) => {
  if (values.length < 2) return 0;
  let peak = values[0];
  let worst = 0;
  for (const value of values.slice(1)) {
    peak = Math.min(peak, value);
    const drawdown = (peak - value) / peak;
    worst = Math.max(worst, drawdown);
  }
  return worst;
};
